18: </div><div class="toast" id="toast"></div><div id="modal-root"></div>
19: <script>
20: const SAVE_KEY='little-orbit-save-v1';
21: const clamp=(n,min=0,max=100)=>Math.max(min,Math.min(max,n));
22: const pick=a=>a[Math.floor(Math.random()*a.length)];
23: const palettes=[{name:'moss',body:'#92b881',light:'#c3d4a0',accent:'#e9be68',ear:'#718d68'},{name:'peach',body:'#edaa8c',light:'#f6c6a8',accent:'#e8d17e',ear:'#cb816e'},{name:'lavender',body:'#b2a1cf',light:'#d7c8e7',accent:'#f2c27d',ear:'#8676ab'},{name:'ocean',body:'#81b9bd',light:'#b4dddd',accent:'#f0c878',ear:'#548b9b'},{name:'butter',body:'#e4c66e',light:'#f4df9b',accent:'#e99b81',ear:'#c49f4b'},{name:'berry',body:'#d996a6',light:'#edc1c1',accent:'#e6c179',ear:'#b66d81'},{name:'sky',body:'#91afd5',light:'#c1d6e9',accent:'#f2ba88',ear:'#718cb8'}];
24: const species=[{name:'Mosskin',emoji:'🌿',ears:'leaf',shape:'round',trait:'patient'},{name:'Pufflet',emoji:'☁️',ears:'round',shape:'puff',trait:'dreamy'},{name:'Mothling',emoji:'🌙',ears:'wing',shape:'tall',trait:'curious'},{name:'Sprout',emoji:'🌱',ears:'sprout',shape:'round',trait:'gentle'},{name:'Pebblit',emoji:'💎',ears:'horn',shape:'chubby',trait:'bold'},{name:'Tidekin',emoji:'🫧',ears:'fin',shape:'tall',trait:'playful'},{name:'Fawnlet',emoji:'🍄',ears:'antler',shape:'chubby',trait:'sweet'}];
25: const gamePool=[{id:'bug',name:'Firefly chase',icon:'✨',desc:'Catch 5 fireflies'},{id:'memory',name:'Moon match',icon:'🌙',desc:'Find the pairs'},{id:'rhythm',name:'Mossy rhythm',icon:'🎵',desc:'Repeat the beat'},{id:'bubble',name:'Bubble pop',icon:'🫧',desc:'Pop 8 bubbles'},{id:'garden',name:'Seed sprint',icon:'🌱',desc:'Gather 5 seeds'},{id:'star',name:'Star hop',icon:'⭐',desc:'Tap 6 falling stars'},{id:'shell',name:'Shell shuffle',icon:'🐚',desc:'Pick the shiny shell'},{id:'cloud',name:'Cloud count',icon:'☁️',desc:'Count the puffs'}];
26: const stages=['Hatchling','Little one','Explorer','Grown-up','Elder'];
27: const needData=[['hunger','🍓','Fullness'],['happiness','☀️','Joy'],['hygiene','🫧','Freshness'],['affection','💗','Love'],['energy','⚡','Energy']];
28: let state=load(),toastTimer,soundOn=false;
29: function load(){try{return JSON.parse(localStorage.getItem(SAVE_KEY))||{pet:null,legacy:[]}}catch{return{pet:null,legacy:[]}}}
30: function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(state))}
31: function uid(){return 'OR-'+Array.from(crypto.getRandomValues(new Uint8Array(4)),x=>x.toString(16).padStart(2,'0')).join('').toUpperCase()}
32: function newPet(){let s=pick(species),p=pick(palettes);let dna=Array.from(crypto.getRandomValues(new Uint8Array(8)),n=>n.toString(16).padStart(2,'0')).join('').toUpperCase();let games=[...gamePool].sort(()=>Math.random()-.5).slice(0,4).map(g=>g.id);return{id:uid(),name:pick(['Pip','Mochi','Bean','Clover','Noodle','Pipkin','Boba','Mallow','Sprig','Pebble','Tofu','Biscuit']),species:s.name,emoji:s.emoji,shape:s.shape,ears:s.ears,trait:s.trait,palette:p,dna,games,born:Date.now(),last:Date.now(),stats:{hunger:82,happiness:80,hygiene:85,affection:76,energy:88},poop:0,stage:0,day:1,cleanCount:0,playCount:0,feedCount:0,careCount:0,asleep:false,score:0,history:[]}}
33: function agePet(p){const elapsed=Math.max(0,Date.now()-p.last),dayMs=10*60*1000; // one tiny-world day is ten real minutes
34: let oldDay=p.day;p.day=Math.min(20,Math.floor((Date.now()-p.born)/dayMs)+1);let stage=Math.min(4,Math.floor((p.day-1)/4));if(stage>p.stage){p.stage=stage;p.history.push({stage,day:p.day});setTimeout(()=>notify(`${p.name} grew into a ${stages[stage].toLowerCase()}! 🌟`),30)}if(p.day>=20){passOn(p);return}let mins=elapsed/60000;p.stats.hunger=clamp(p.stats.hunger-mins*1.6);p.stats.happiness=clamp(p.stats.happiness-mins*.85);p.stats.hygiene=clamp(p.stats.hygiene-mins*.7);p.stats.affection=clamp(p.stats.affection-mins*.5);p.stats.energy=clamp(p.stats.energy+(p.asleep?mins*2.7:-mins*.55));if(p.stats.hunger<23||p.stats.hygiene<20||p.stats.affection<18)p.stats.happiness=clamp(p.stats.happiness-mins*1.1);if(p.stats.happiness<8&&Math.random()<.05*mins)p.stats.energy=clamp(p.stats.energy-3);if(elapsed>0&&Math.random()<Math.min(.6,mins*.22)){p.poop=Math.min(4,p.poop+1)}p.last=Date.now()}
35: function passOn(p){p.day=20;p.stats.happiness=clamp(p.stats.happiness);state.legacy.unshift({id:p.id,name:p.name,species:p.species,emoji:p.emoji,palette:p.palette,dna:p.dna,stage:p.stage,days:20,score:p.score,history:p.history,stats:{...p.stats},born:p.born});state.pet=null;save();notify(`${p.name} has joined the stars. Their story lives on in your collection. ✨`)}
36: function hatch(){state.pet=newPet();save();render();notify(`A new ${state.pet.species} hatched! Say hello to ${state.pet.name}.`)}
37: function petSvg(p){let c=p.palette,scale=[.82,.9,.98,1.07,1.15][p.stage],rx=p.shape==='tall'?61:p.shape==='puff'?73:68,ry=p.shape==='tall'?78:p.shape==='chubby'?62:68;let ear='';if(p.ears==='leaf')ear='<path d="M72 85 Q36 17 89 47 Q96 64 83 88 M148 85 Q183 17 131 47 Q123 64 137 88" fill="'+c.ear+'" stroke="'+c.body+'" stroke-width="6"/>';else if(p.ears==='wing')ear='<path d="M72 88 Q15 37 31 96 Q43 125 76 112 M148 88 Q205 37 189 96 Q177 125 144 112" fill="'+c.light+'" stroke="'+c.body+'" stroke-width="5"/>';else if(p.ears==='sprout')ear='<path d="M105 56 Q83 21 102 19 Q123 29 108 57 M111 54 Q124 11 143 26 Q142 47 112 60" fill="'+c.ear+'" stroke="'+c.body+'" stroke-width="4"/>';else if(p.ears==='horn')ear='<path d="M76 84 L61 36 Q88 43 94 79 M143 79 Q151 43 178 36 L160 85" fill="'+c.light+'" stroke="'+c.body+'" stroke-width="5"/>';else if(p.ears==='fin')ear='<path d="M76 84 Q31 32 49 27 Q78 41 91 76 M145 76 Q159 41 188 27 Q204 32 160 84" fill="'+c.light+'" stroke="'+c.body+'" stroke-width="5"/>';else ear='<path d="M69 90 Q52 25 86 43 Q96 55 87 90 M151 90 Q166 25 134 43 Q124 55 133 90" fill="'+c.ear+'" stroke="'+c.body+'" stroke-width="6"/>';let eye=p.stats.energy<18?'<path d="M78 129q9 7 18 0 M126 129q9 7 18 0" fill="none" stroke="#34453b" stroke-width="5" stroke-linecap="round"/>':'<ellipse cx="86" cy="128" rx="5.5" ry="8" fill="#34453b"/><ellipse cx="136" cy="128" rx="5.5" ry="8" fill="#34453b"/><circle cx="88" cy="125" r="2" fill="white"/><circle cx="138" cy="125" r="2" fill="white"/>';let stageMark=p.stage>=2?'<path d="M109 65 l4 9 10 1-7 7 2 10-9-5-9 5 2-10-7-7 10-1z" fill="'+c.accent+'"/>':'';let wings=p.species==='Mothling'?'<ellipse cx="51" cy="135" rx="28" ry="39" fill="'+c.light+'" opacity=".8"/><ellipse cx="171" cy="135" rx="28" ry="39" fill="'+c.light+'" opacity=".8"/>':'';return `<svg class="pet-svg ${p.asleep?'sleeping':''}" id="pet-svg" viewBox="0 0 220 230" role="img" aria-label="${p.name}, a ${p.species}"><g transform="translate(0 ${((1-scale)*100).t... (line truncated to 2000 chars)
38: function mood(p){if(!p)return'💤';if(p.asleep)return'💤';if(p.stats.hunger<24)return'🥺';if(p.stats.hygiene<25)return'😵‍💫';if(p.stats.happiness>75)return'💖';if(p.stats.energy<20)return'😴';return'😊'}
39: function notify(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
40: function render(){let p=state.pet;if(p){agePet(p);p=state.pet}document.getElementById('day-pill').textContent=p?`🌱 Day ${p.day} of 20`:'🌱 Waiting for a hatchling';let area=document.getElementById('pet-area');if(!p){area.innerHTML='<div class="scene-empty"><div class="egg-card"><span class="egg">🥚</span><h2>A little life, waiting</h2><p>Every egg carries a one-of-a-kind soul. Tap to hatch your new friend and begin your story together.</p><button class="primary" onclick="hatch()">Hatch your egg ✨</button></div></div>'}else{area.innerHTML=petSvg(p)+`<div class="pet-name-tag">${p.name} · ${p.species}</div><div class="pet-mood">${mood(p)}</div>${p.poop?`<button class="poop" onclick="care('clean')" aria-label="Clean up waste">💩</button>`:''}`;document.querySelector('.scene-empty')?.remove()}
41: let title=document.getElementById('pet-title'),subtitle=document.getElementById('pet-subtitle'),avatar=document.getElementById('profile-avatar'),badge=document.getElementById('stage-badge');if(p){title.textContent=p.name;subtitle.textContent=`${p.species} · ${p.trait} · age ${p.day} ${p.day===1?'day':'days'}`;avatar.innerHTML=petSvg(p).replace('class="pet-svg','class="pet-svg mini-svg');badge.textContent=stages[p.stage]}else{title.textContent='An egg is waiting';subtitle.textContent='Your next tiny adventure starts here';avatar.textContent='🥚';badge.textContent='Unhatched'}
42: let meters=document.getElementById('meters');meters.innerHTML=p?needData.map(([key,icon,label])=>`<div><div class="meter-label"><span>${icon} ${label}</span><span>${Math.round(p.stats[key])}%</span></div><div class="track"><div class="fill ${p.stats[key]<25?'low':p.stats[key]<50?'mid':''}" style="width:${p.stats[key]}%"></div></div></div>`).join(''):'<p class="empty-needs">Your hatchling’s needs will appear here. Keep their tummy full and little heart bright.</p>';
43: let acts=[['feed','🍓','Feed'],['play','🪁','Play'],['love','💗','Cuddle'],['clean','🧹','Clean up'],['shower','🚿','Bathe'],['treat','🎁','Treat']];document.getElementById('care-actions').innerHTML=acts.map(([id,e,n])=>`<button class="action" onclick="care('${id}')" ${!p?'disabled':''}><span class="emoji">${e}</span><span>${n}</span></button>`).join('');document.getElementById('care-note').textContent=p?(p.poop?`${p.name} left ${p.poop} little mess${p.poop>1?'es':''}. A tidy home means a happy heart.`:`${p.name} is ${p.trait}. Their unique DNA: ${p.dna.slice(0,4)} · ${p.dna.slice(4,8)} · ${p.dna.slice(8,12)} · ${p.dna.slice(12)}`):'Every little gesture helps your new friend thrive.';
44: let gs=document.getElementById('games-list');gs.innerHTML=p?p.games.map(id=>{let g=gamePool.find(x=>x.id===id);return `<button class="game-btn" onclick="startGame('${id}')" ${p.stats.energy<10||p.asleep?'disabled':''}><span class="game-icon">${g.icon}</span><span><strong>${g.name}</strong><small>${g.desc}</small></span></button>`}).join(''):'<div class="games-locked">Hatch your egg to discover the four games your pet loves most.</div>';document.getElementById('game-count').textContent=p?'4 games · '+p.playCount+' played':'4 games per lifetime';document.getElementById('sleep-btn').textContent=p?(p.asleep?'☀️ Wake up':'🌙 Lights out'):'🌙 Lights out';document.getElementById('sleep-btn').disabled=!p;
45: let legacy=document.getElementById('legacy-list');legacy.innerHTML=state.legacy.length?state.legacy.slice(0,3).map(x=>`<div class="legacy-row"><span class="legacy-creature">${x.emoji}</span><div><strong>${x.name}</strong><small>${x.species} · ${stages[x.stage]} · DNA ${x.dna.slice(0,8)}</small></div><span class="legacy-count">${x.score} ✦</span></div>`).join(''):'<p class="legacy-empty">Your first little life will live here forever.</p>';document.getElementById('last-care').textContent=p?`${p.poop?`💩 ${p.poop} mess${p.poop>1?'es':''} to tidy`:'A little love goes a long way'} · ${p.score} ✦`:'A little love goes a long way';save()}
46: function animate(className){let svg=document.getElementById('pet-svg');if(svg){svg.classList.remove('bounce','shake');void svg.offsetWidth;svg.classList.add(className);setTimeout(()=>svg.classList.remove(className),650)}}
47: function care(action){let p=state.pet;if(!p)return;if(p.asleep&&action!=='clean'){notify(`${p.name} is sleeping. Wake them gently first.`);return}let m=p.stats;let lines={feed:['A berry snack! Yum! 🍓',()=>{m.hunger=clamp(m.hunger+29);m.happiness=clamp(m.happiness+4);p.feedCount++}],play:['A lovely play together! 🪁',()=>{m.happiness=clamp(m.happiness+19);m.energy=clamp(m.energy-9);m.affection=clamp(m.affection+4);p.playCount++}],love:['A big, warm cuddle. 💗',()=>{m.affection=clamp(m.affection+22);m.happiness=clamp(m.happiness+11)}],clean:['All clean and cozy! 🧹',()=>{if(!p.poop){m.hygiene=clamp(m.hygiene+4)}else{p.cleanCount+=p.poop;p.poop=0;m.hygiene=clamp(m.hygiene+18);m.happiness=clamp(m.happiness+8)}}],shower:['Fresh as a daisy! 🚿',()=>{m.hygiene=clamp(m.hygiene+31);m.happiness=clamp(m.happiness+5)}],treat:['A tiny surprise! 🎁',()=>{m.hunger=clamp(m.hunger+10);m.happiness=clamp(m.happiness+15);m.affection=clamp(m.affection+8)}]};lines[action][1]();p.careCount++;p.score+=2;p.last=Date.now();animate(action==='play'?'bounce':'shake');notify(lines[action][0]);render()}
48: function toggleSleep(){let p=state.pet;if(!p)return;p.asleep=!p.asleep;p.last=Date.now();notify(p.asleep?`${p.name} is tucked in. Sweet dreams! 🌙`:`Good morning, ${p.name}! ☀️`);render()}
