1: /* Little Orbit: deeper care, evolution, play, and sound systems. */
2: const originalRender = render;
3: const originalPetSvg = petSvg;
4: stages.splice(0, stages.length, 'Tiny baby', 'Teenager', 'Adult', 'Elderly adult');
5: const WORLD_DAY = 10 * 60 * 1000;
6: const SLEEP_LENGTH = 30 * 60 * 1000;
7: const foods = [
8:   {id:'berry',name:'Moonberry',icon:'🫐',desc:'A light, happy snack',full:14,energy:5,joy:10},
9:   {id:'cake',name:'Honey cake',icon:'🍰',desc:'Sweet and filling',full:28,energy:2,joy:15},
10:   {id:'carrot',name:'Star carrot',icon:'🥕',desc:'A crunchy energy boost',full:20,energy:17,joy:4},
11:   {id:'soup',name:'Comet soup',icon:'🥣',desc:'Warm, nourishing comfort',full:23,energy:11,joy:9},
12:   {id:'apple',name:'Cloud apple',icon:'🍎',desc:'A balanced little bite',full:19,energy:8,joy:8}
13: ];
14: let activeGame = null;
15: let activityTimer = null;
16: 
17: function stageForDay(day){ return day>=15?3:day>=10?2:day>=5?1:0; }
18: function agePet(p){
19:   if(!p) return;
20:   const now=Date.now(), elapsed=Math.max(0,now-(p.last||now));
21:   p.day=Math.min(20,Math.floor(Math.max(0,now-p.born)/WORLD_DAY)+1);
22:   const nextStage=stageForDay(p.day);
23:   if(nextStage>(p.stage||0)){
24:     p.stage=nextStage;
25:     p.history=p.history||[];
26:     p.history.push({stage:nextStage,day:p.day,at:now});
27:     setTimeout(()=>notify(`${p.name} evolved into a ${stages[nextStage]}! ✨`),50);
28:     sound('evolve');
29:   }
30:   if(p.day>=20){passOn(p);return;}
31:   const mins=elapsed/60000;
32:   p.stats=p.stats||{hunger:80,happiness:80,hygiene:80,affection:80,energy:80};
33:   p.asleep=!!p.asleep;
34:   if(p.asleep && p.sleepUntil && now>=p.sleepUntil){
35:     p.asleep=false;p.groggyUntil=0;p.stats.energy=clamp(p.stats.energy+8);
36:     notify(`${p.name} wakes up refreshed after a cozy 30 minutes. ☀️`);sound('wake');
37:   }
38:   p.stats.hunger=clamp(p.stats.hunger-mins*(p.asleep?.65:1.6));
39:   p.stats.happiness=clamp(p.stats.happiness-mins*(p.asleep?.2:.85));
40:   p.stats.hygiene=clamp(p.stats.hygiene-mins*.7);
41:   p.stats.affection=clamp(p.stats.affection-mins*.5);
42:   p.stats.energy=clamp(p.stats.energy+(p.asleep?mins*2.7:-mins*.55));
43:   if(p.stats.hunger<23||p.stats.hygiene<20||p.stats.affection<18)p.stats.happiness=clamp(p.stats.happiness-mins*1.1);
44:   if(elapsed>0&&Math.random()<Math.min(.6,mins*.22))p.poop=Math.min(4,(p.poop||0)+1);
45:   if(p.groggyUntil&&now>=p.groggyUntil)p.groggyUntil=0;
46:   p.last=now;
47: }
48: function passOn(p){
49:   if(!p||state.pet!==p)return;
50:   p.day=20;p.stage=3;p.history=p.history||[];
51:   if(!p.history.some(h=>h.stage===3))p.history.push({stage:3,day:15,at:p.born+14*WORLD_DAY});
52:   const keepsake={id:p.id,name:p.name,species:p.species,emoji:p.emoji,shape:p.shape,ears:p.ears,trait:p.trait,palette:p.palette,dna:p.dna,stage:3,days:20,score:p.score||0,history:p.history,stats:{...p.stats},born:p.born,games:[...(p.games||[])],playCount:p.playCount||0};
53:   state.legacy=state.legacy||[];state.legacy.unshift(keepsake);state.pet=null;save();
54:   notify(`${p.name} has completed their journey and returned to an egg. Their whole story is in Little Legacies. 🥚`);
55: }
56: function petSvg(p){
57:   let svg=originalPetSvg(p);
58:   const adornments=[
59:     '',
60:     `<path d="M65 104 Q110 84 155 104" fill="none" stroke="${p.palette.accent}" stroke-width="9" stroke-linecap="round"/><circle cx="110" cy="99" r="7" fill="${p.palette.light}"/>`,
61:     `<path d="M76 183 Q110 197 144 183 L139 207 Q110 218 81 207Z" fill="${p.palette.accent}" stroke="${p.palette.ear}" stroke-width="3"/><circle cx="110" cy="198" r="6" fill="${p.palette.light}"/>`,
62:     `<g fill="none" stroke="#607269" stroke-width="4"><circle cx="86" cy="128" r="13"/><circle cx="136" cy="128" r="13"/><path d="M99 128h24M73 124l-7-3M149 124l7-3"/></g><path d="M91 166 Q110 178 129 166" fill="none" stroke="#fff4da" stroke-width="8" stroke-linecap="round"/>`
63:   ];
