function agePet(p){
  if(!p) return;
  const now=Date.now(), elapsed=Math.max(0,now-(p.last||now));
  p.day=Math.min(20,Math.floor(Math.max(0,now-p.born)/WORLD_DAY)+1);
  const nextStage=stageForDay(p.day);
  if(nextStage>(p.stage||0)){
    p.stage=nextStage;
    p.history=p.history||[];
    p.history.push({stage:nextStage,day:p.day,at:now});
    setTimeout(()=>notify(`${p.name} evolved into a ${stages[nextStage]}! ✨`),50);
    sound('evolve');
  }
  if(p.day>=20){passOn(p);return;}
  const mins=elapsed/60000;
  p.stats=p.stats||{hunger:80,happiness:80,hygiene:80,affection:80,energy:80};
  p.asleep=!!p.asleep;
  if(p.asleep && p.sleepUntil && now>=p.sleepUntil){
    p.asleep=false;p.groggyUntil=0;p.stats.energy=clamp(p.stats.energy+8);
    notify(`${p.name} wakes up refreshed after a cozy 30 minutes. ☀️`);sound('wake');
  }
  p.stats.hunger=clamp(p.stats.hunger-mins*(p.asleep?.65:1.6));
  p.stats.happiness=clamp(p.stats.happiness-mins*(p.asleep?.2:.85));
  p.stats.hygiene=clamp(p.stats.hygiene-mins*.7);
  p.stats.affection=clamp(p.stats.affection-mins*.5);
  p.stats.energy=clamp(p.stats.energy+(p.asleep?mins*2.7:-mins*.55));
  if(p.stats.hunger<23||p.stats.hygiene<20||p.stats.affection<18)p.stats.happiness=clamp(p.stats.happiness-mins*1.1);
  if(elapsed>0&&Math.random()<Math.min(.6,mins*.22))p.poop=Math.min(4,(p.poop||0)+1);
  if(p.groggyUntil&&now>=p.groggyUntil)p.groggyUntil=0;
  p.last=now;
}

