211: let audioContext=null,musicTimer=null,musicStep=0;
212: function getAudioContext(){
213:   const AudioContextClass=window.AudioContext||window.webkitAudioContext;
214:   if(!AudioContextClass)return null;
215:   if(!audioContext)audioContext=new AudioContextClass();
216:   if(audioContext.state==='suspended')audioContext.resume();
217:   return audioContext;
218: }
219: function playTone(frequency,duration=.16,wave='sine',volume=.045,delay=0){
220:   const ctx=getAudioContext();if(!ctx)return;
221:   const osc=ctx.createOscillator(),gain=ctx.createGain(),start=ctx.currentTime+delay;
222:   osc.type=wave;osc.frequency.setValueAtTime(frequency,start);
223:   gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(volume,start+.015);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);
224:   osc.connect(gain);gain.connect(ctx.destination);osc.start(start);osc.stop(start+duration+.03);
225: }
