  if(p.groggyUntil>Date.now()&&action==='play'){notify(`${p.name} is still a little groggy. Try again after a gentle rest.`);return;}
  const m=p.stats;
  if(action==='play'){m.happiness=clamp(m.happiness+19);m.energy=clamp(m.energy-9);m.affection=clamp(m.affection+4);p.playCount=(p.playCount||0)+1;animate('bounce');showActivity('🪁','playing');sound('play');notify(`${p.name} zips after the kite!`);}
