const nextStage=stageForDay(p.day);
p.history=Array.isArray(p.history)?p.history:[];
if(nextStage>(p.stage||0)){
  const previousStage=p.stage||0;
  for(let stage=previousStage+1;stage<=nextStage;stage++){
